/* GSA LIFE · browser UI */
(() => {
'use strict';
const E=window.GSAEngine, KEY='gsa-life-v1';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',journal:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',cap:'m2 9 10-5 10 5-10 5z M6 11v6q6 5 12 0v-6 M22 9v8',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',ball:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3v18 M5.6 5.6q12 1 12.8 12.8 M5.6 18.4q1-12 12.8-12.8',flask:'M9 3h6 M10 3v7L4 20h16l-6-10V3 M7 15h10',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',moon:'M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13',flag:'M5 21V3q4-2 8 0t8 0v10q-4 2-8 0t-8 0',refresh:'M20 7V2 M20 7h-5 M20 7a9 9 0 1 0 1 9',arrow:'M4 12h16 m-6-6 6 6-6 6',check:'m4 12 5 5L20 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2'};
function icon(k){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.spark}"/></svg>`}
const campus=`<svg class="campus" viewBox="0 0 600 270" fill="none" aria-hidden="true"><circle cx="478" cy="62" r="30" fill="#f9e6ab"/><path d="M0 180 120 79 220 157 335 58 490 159 570 105 650 180v90H0Z" fill="#dbe6cf"/><path d="m0 213 140-83 126 76 119-75 156 82 59-10v67H0Z" fill="#cbdcbd"/><path d="M30 246h570v24H30z" fill="#bed0af"/><path d="m150 233 125-20 292 20-75 20-342 4z" fill="#aabc9a" opacity=".45"/><path d="M193 116h285v119H193z" fill="#f7f5e8"/><path d="M193 116h285v13H193z" fill="#95ad8b"/><path d="M193 163h285v6H193zM193 202h285v6H193z" fill="#e1e2d0"/><path d="M213 140h24v16h-24zM250 140h24v16h-24zM365 140h24v16h-24zM403 140h24v16h-24zM441 140h19v16h-19zM213 178h24v16h-24zM250 178h24v16h-24zM365 178h24v16h-24zM403 178h24v16h-24zM441 178h19v16h-19zM213 216h24v15h-24zM250 216h24v15h-24zM365 216h24v15h-24zM403 216h24v15h-24zM441 216h19v15h-19z" fill="#b3c8b2"/><path d="M287 98h67v139h-67z" fill="#e9ebdb"/><path d="M281 93h79v9h-79z" fill="#6e916f"/><path d="M304 202h33v35h-33z" fill="#789879"/><path d="M320 202v35" stroke="#c2d0b7" stroke-width="2"/><circle cx="320" cy="129" r="15" fill="#fafbf0" stroke="#a0b596" stroke-width="2"/><path d="M320 119v11l7 4" stroke="#789076" stroke-width="2"/><path d="M300 167h41v17h-41z" fill="#b3c8b2"/><path d="M100 244v-67M148 238v-66M509 240v-78M550 243v-52" stroke="#8c9e74" stroke-width="5"/><ellipse cx="100" cy="175" rx="25" ry="36" fill="#8eaf7e"/><ellipse cx="148" cy="166" rx="20" ry="30" fill="#a1bb8a"/><ellipse cx="509" cy="165" rx="24" ry="38" fill="#87a877"/><ellipse cx="550" cy="189" rx="19" ry="29" fill="#a3bd89"/><path d="M290 237h61l40 33H251z" fill="#e4e5ce"/><path d="M177 231v-36h-23" stroke="#96a789" stroke-width="3"/><path d="M145 188h17v13h-17z" fill="#e9ecdd" stroke="#96a789" stroke-width="2"/><path d="M150 202h9" stroke="#b38c62" stroke-width="2"/><circle cx="247" cy="239" r="4" fill="#637d65"/><path d="M247 245v10m0-7 5 3m-5 4-3 7m3-7 3 7" stroke="#637d65" stroke-width="3"/><circle cx="390" cy="242" r="4" fill="#b39f78"/><path d="M390 248v9m0-6 5 2m-5 4-3 7m3-7 3 7" stroke="#b39f78" stroke-width="3"/><path d="m414 73 5-3 5 3m-31 11 4-3 5 3" stroke="#a5b694" stroke-width="2"/></svg>`;
let state=null,draft=E.create('새로운 학생'),view='home',action='study',mode='normal',semesterNotice=null,toastTimer,storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw){const v=JSON.parse(raw);if(v.version===1&&v.state&&typeof v.state.turn==='number'&&v.state.stats&&Array.isArray(v.state.grades))state=v.state;}}catch(e){storageOK=false;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,state}));storageOK=true;}catch(e){storageOK=false;toast('저장 공간에 접근할 수 없어 이번 진행은 저장되지 않아요.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function clubName(list,id){return list.find(x=>x.id===id)?.name||'미가입'}
function shell(body){const nav=[['home','home','학교생활'],['grades','book','성적표'],['clubs','people','동아리·학생회'],['journal','journal','나의 기록'],['future','cap','대학 진학']];$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">g.</div><span>GSA LIFE</span></div><div class="brand-sub">THREE YEARS, YOUR STORY</div><div class="nav-label">MY SCHOOL LIFE</div><nav class="nav">${nav.map(([id,i,n])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${!state&&id!=='home'?'disabled':''} ${view===id?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note"><strong>정답이 없는 3년.</strong>어떤 학생으로 기억될지는<br>너의 선택에 달려 있어.</div><button class="new-btn" data-do="new">${icon('refresh')}<span>새로운 학교생활</span></button></div></aside><main class="layout"><header class="topbar"><div class="breadcrumb"><span class="welcome-small">GSA LIFE &nbsp; / &nbsp; </span>나의 캠퍼스 &nbsp; / &nbsp; <b>${nav.find(n=>n[0]===view)?.[2]||'입학하기'}</b></div><div class="top-right"><span class="save-status">${state?(storageOK?'이 브라우저에 자동 저장':'저장 사용 불가'):'나만의 3년을 시작해요'}</span><button class="new-mobile" data-do="new" aria-label="새로운 학교생활">↻</button><div class="avatar" aria-label="학생 프로필">${esc((state?.name||'G').slice(0,1))}</div></div></header>${body}<footer class="footer">GSA LIFE · 나의 광주과학고 3년 &nbsp; / &nbsp; 비공식 팬 시뮬레이터<br>8턴을 한 학기로 압축한 게임입니다. 과목·학점·동아리·입시 결과는 게임용 설정이며 실제 학교 규정이나 입시 예측이 아닙니다.</footer></main>`;bind();}
function statCards(s,cls='stats-grid'){const items=[['intelligence','지능','spark'],['social','사회성','people'],['athletics','운동','ball'],['discipline','자기관리','book']];return `<div class="${cls}">${items.map(([k,l,i])=>`<div class="card stat"><div class="stat-top">${icon(i)}${l}</div><div class="stat-value">${Math.round(s[k])}<small>/ 100</small></div><div class="bar" role="meter" aria-label="${l}" aria-valuenow="${Math.round(s[k])}" aria-valuemin="0" aria-valuemax="100"><span style="width:${s[k]}%"></span></div></div>`).join('')}</div>`}
function heading(k,t,d,tag='FIRST PLAYABLE · v0.1'){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div><span class="tag">${tag}</span></div>`}
function setup(){shell(`${heading('YOUR NEXT CHAPTER','열일곱, 새로운 시작.','광주과학고에서 보낼 3년. 어떤 이야기를 만들어갈까?')}<section class="hero"><div class="hero-copy"><div class="hero-kicker"><span class="badge-dark">GSA</span> 입학을 환영합니다</div><h2>같은 학교, 다른 인생.<br>이번 주는 네가 정해.</h2><p>실험실의 밤, 체육관의 함성, 친구와의 대화.<br>성적표에 담기지 않는 순간까지, 너의 3년.</p></div>${campus}</section><div class="setup-columns"><section class="card setup-panel"><h2>나의 입학 카드</h2><p>타고난 수치는 출발점일 뿐. 입학 후의 선택으로 달라집니다.</p><div class="form-grid"><label class="field full">이름 또는 별명<input id="student-name" maxlength="16" placeholder="어떤 이름으로 기억될까?" autocomplete="off" value="${draft.name==='새로운 학생'?'':esc(draft.name)}"></label><label class="field">학술동아리<select id="academic-club">${E.academicClubs.map(c=>`<option value="${c.id}" ${draft.academicClub===c.id?'selected':''}>${c.name}</option>`).join('')}</select><small>탐구 경험을 쌓고 연구의 방향을 찾아요.</small></label><label class="field">상설·운동 동아리<select id="activity-club">${E.activityClubs.map(c=>`<option value="${c.id}" ${draft.activityClub===c.id?'selected':''}>${c.name}</option>`).join('')}</select><small>팀 활동과 친구 관계가 달라져요.</small></label></div><div class="row" style="margin-top:27px"><strong style="font-size:12px">무작위로 만난 나</strong><button class="secondary" data-do="reroll">↻ 능력치 다시 뽑기</button></div>${statCards(draft.stats,'setup-stats')}<small style="font-size:10px">초기 능력치는 무작위로 정해져요. 모든 능력은 활동으로 성장합니다.</small><button class="primary" data-do="start">입학하고, 나의 3년 시작하기 ${icon('arrow')}</button></section><aside class="card setup-panel"><div class="eyebrow">A LITTLE GUIDE</div><h2 style="margin-top:12px">너의 3년 미리보기</h2>${[['01','일주일에 하나의 선택','공부, 연구, 운동, 친구, 휴식. 한정된 시간 속에서 나만의 균형을 찾아요.'],['02','시험과 선택과목','4·8주차는 시험. 2학년 2학기부터 관심 있는 선택과목 2개를 골라요.'],['03','학교 안의 또 다른 나','동아리 활동, 학생회 선거, 연구 발표. 새로운 기회가 찾아옵니다.'],['04','졸업, 그리고 다음 장','6학기의 성적과 활동을 모아 대학에 지원하고 나만의 결말을 확인해요.']].map(([n,t,d])=>`<div class="step-note"><span class="step-num">${n}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}<div class="tip" style="margin-top:18px"><h3>천천히, 네 속도로</h3><p>진행은 이 브라우저에 자동 저장됩니다. 다음에 돌아와 이어서 플레이하세요.</p></div></aside></div>`)}
function timeline(){const p=E.getPhase(state);return `<div class="timeline" aria-label="6학기 진행도">${Array.from({length:6},(_,i)=>`<div class="term ${i<Math.floor(state.turn/8)?'done':i===Math.floor(state.turn/8)?'current':''}"><span>${Math.floor(i/2)+1}학년 ${i%2+1}학기</span><small>${i<Math.floor(state.turn/8)?'완료':i===Math.floor(state.turn/8)?`${p.week} / 8주`:''}</small></div>`).join('')}</div>`}
function recentLog(limit=4){return state.log.slice(0,limit).map(l=>`<div class="journal-item"><small>${esc(l.label||`학교생활 ${l.turn||0}주차`)}</small><p>${esc(l.message||l.text||l)}</p></div>`).join('')||'<p style="font-size:11px;color:#8b977f">첫 번째 이야기를 기다리고 있어요.</p>'}
function profile(){const p=E.getProfile(state);return `<section class="card profile"><div class="profile-head"><div class="avatar">${esc(state.name.slice(0,1))}</div><div><strong>${esc(state.name)}</strong><small>${esc(p.rankLabel||'나만의 가능성을 찾는 중')}</small></div></div>${[['health','컨디션',''],['stress','스트레스','stress']].map(([k,l,c])=>`<div class="meter ${c}"><div class="row"><span>${l}</span><b>${Math.round(state.stats[k])} / 100</b></div><div class="bar"><span style="width:${state.stats[k]}%"></span></div></div>`).join('')}<div class="profile-divider"></div><div class="metric"><span>누적 평점</span><strong class="gpa">${state.grades.length?p.gpa.toFixed(2):'—'} <small style="font-size:10px">/ 4.3</small></strong></div><div class="metric"><span>연구 역량</span><strong>${Math.round(state.stats.research)}</strong></div><div class="metric"><span>리더십</span><strong>${Math.round(state.stats.leadership)}</strong></div><div class="metric"><span>학생회</span><strong>${esc(state.councilRole||'일반 학생')}</strong></div><div class="profile-divider"></div><div class="club-pill">${icon('flask')}${esc(clubName(E.academicClubs,state.academicClub))}</div><div class="club-pill">${icon('people')}${esc(clubName(E.activityClubs,state.activityClub))}</div></section>`}
function home(){if(state.turn>=48){future();return;}const p=E.getPhase(state);const termLabel=`${p.year}학년 ${p.semester}학기`;const tips=state.stats.stress>65?'스트레스가 높아졌어요. 산책과 휴식으로 잠깐 숨을 돌려도 괜찮아요.':state.stats.health<45?'컨디션이 떨어졌어요. 시험 준비도 중요하지만 충분한 휴식이 학습 효율을 지켜줘요.':p.exam?'시험 주간이에요. 자습을 추가하면 준비도가 오르지만, 무리하면 다음 주 컨디션에 영향을 줘요.':'작은 선택이 쌓여 너의 이야기가 됩니다. 공부와 활동 사이에 너만의 리듬을 찾아보세요.';
shell(`${heading('MY SCHOOL LIFE',`${termLabel}, ${p.week}주차`,`${esc(state.name)}의 이번 주에는 어떤 일이 기다릴까?`,p.exam?'EXAM WEEK':'YOUR STORY IS GROWING')}${timeline()}<section class="hero"><div class="hero-copy"><div class="hero-kicker"><span class="badge-dark">${termLabel}</span> ${p.exam?'시험 주간':state.turn<8?'새로운 시작의 계절':'우리의 이야기가 자라는 시간'}</div><h2>${p.exam?'쌓아온 시간이<br>너의 실력이 될 거야.':state.turn<8?'아직은 낯선 교정,<br>가능성은 무한하니까.':state.turn<32?'조금씩 선명해지는<br>나만의 방향.':'어느새 가까워진 졸업,<br>마지막까지 나답게.'}</h2><p>${p.exam?'준비도와 컨디션, 오늘은 어떤 균형을 선택할까?':'잘하는 것과 좋아하는 것 사이,<br>오늘도 나를 알아가는 하루.'}</p></div>${campus}</section><div class="columns"><div><div class="section-title"><h2>조금씩 성장하는 나</h2><small>모든 능력치는 100점 기준</small></div>${statCards(state.stats)}<div class="section-title"><h2>이번 주, 무엇을 할까?</h2><small>활동 1개를 선택하세요</small></div>${p.exam?`<section class="exam-box"><h3>${p.week===4?'중간고사':'기말고사'} · 자습 계획</h3><p>기본 수업과 자습은 자동 진행돼요. 추가 자습은 시험 준비와 피로에 함께 영향을 줍니다.</p><div class="study-options">${[['normal','기본 자습'],['dawn','새벽 자습'],['night','심야 자습']].map(([id,n])=>`<button data-mode="${id}" class="${mode===id?'active':''}" aria-pressed="${mode===id}">${n}</button>`).join('')}</div></section>`:''}<div class="action-grid">${E.actions.map(a=>`<button class="action ${action===a.id?'selected':''}" data-action="${a.id}" aria-pressed="${action===a.id}"><div class="action-icon">${icon(({study:'book',train:'ball',academic:'flask',club:'people',research:'flask',friends:'heart',rest:'moon',council:'flag'})[a.id]||a.icon)}</div><span class="radio-dot"></span><div><h3>${esc(a.id==='club'&&state.activityClub==='none'?'자율 활동':a.name)}</h3><p>${esc(a.id==='club'&&state.activityClub==='none'?'내 시간을 확보하고 몸과 마음을 정돈해요.':a.description)}</p><div class="effect">${esc(a.id==='club'&&state.activityClub==='none'?'컨디션 ↑ · 자기관리 ↑ · 스트레스 ↓':a.effectsText)}</div></div></button>`).join('')}</div><button class="primary advance" data-do="advance"><span>${esc(E.actions.find(a=>a.id===action)?.name||'활동 선택')}하고 한 주 보내기</span><span style="display:flex;align-items:center;gap:10px"><small>WEEK ${state.turn+1} / 48</small>${icon('arrow')}</span></button><p class="action-foot">기본 수업은 자동으로 진행됩니다 · 선택에 따라 성장과 사건이 달라져요</p></div><aside class="right-column">${profile()}<div class="tip"><h3>✦ 이번 주의 작은 조언</h3><p>${tips}</p></div><section class="card journal"><h3>최근의 순간들</h3>${recentLog()}</section></aside></div>`);}
function grades(){const p=E.getProfile(state);shell(`${heading('ACADEMIC RECORD','숫자에 담긴 노력들.','학기가 끝날 때마다, 너의 성적표가 채워집니다.','TRANSCRIPT')}${timeline()}<div class="summary-cards"><div class="card summary-card"><small>누적 평점 / 4.3</small><strong>${state.grades.length?p.gpa.toFixed(2):'—'}</strong></div><div class="card summary-card"><small>이수 학점</small><strong>${p.credits}</strong></div><div class="card summary-card"><small>마친 학기</small><strong>${state.grades.length} <small>/ 6</small></strong></div></div><div class="notice">학점은 과목별 단위 수, 평점은 성취도를 나타내요. 누적 평점은 F를 포함한 수강 학점을 가중치로 계산합니다. 게임용 4.3점 체계입니다.</div>${state.grades.length?state.grades.map(g=>`<details class="card details" open><summary><strong>${g.year}학년 ${g.semester}학기</strong><span>평점 ${g.gpa.toFixed(2)} · ${g.earnedCredits ?? g.credits}학점 이수</span></summary><div class="table-wrap"><table><thead><tr><th>과목</th><th>과목 학점</th><th>성취 점수</th><th>등급</th><th>평점</th></tr></thead><tbody>${g.subjects.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.credits}</td><td>${s.score.toFixed(1)}</td><td>${esc(s.grade)}</td><td>${s.point.toFixed(1)}</td></tr>`).join('')}</tbody></table></div></details>`).join(''):`<div class="card empty">아직 완성된 성적표가 없어요.<br>1학년 1학기 8주차를 마치면 첫 성적을 확인할 수 있어요.</div>`}<div class="section-title" style="margin-top:25px"><h2>이번 학기 수강 과목</h2></div><div class="notice">${E.getSubjects(state).map(s=>`${esc(s.name)} (${s.credits}학점)`).join(' · ')}<br>선택과목은 2학년 2학기 시작에 2개를 고릅니다.</div>`)}
function clubs(){shell(`${heading('BEYOND THE CLASSROOM','교실 밖의 또 다른 나.','함께 땀 흘리고, 질문하고, 무언가를 만들어가는 시간.','CAMPUS COMMUNITY')}<div class="club-grid"><section class="card club-card"><div class="big-icon">⚗</div><div class="eyebrow">ACADEMIC CLUB</div><h3 style="margin-top:12px">${esc(clubName(E.academicClubs,state.academicClub))}</h3><p>동아리 활동과 연구 프로젝트를 통해 탐구 경험을 쌓아요. 학술동아리 분야와 선택과목이 맞으면 학습에 도움이 됩니다.</p><span class="tag">${state.captain&&state.activityClub==='none'?'학술동아리 기장 · ':''}연구 역량 ${Math.round(state.stats.research)} / 100</span></section><section class="card club-card"><div class="big-icon">◉</div><div class="eyebrow">AFTER SCHOOL</div><h3 style="margin-top:12px">${esc(clubName(E.activityClubs,state.activityClub))}</h3><p>훈련과 동아리 활동으로 친구들과 가까워져요. 꾸준히 참여하면 동아리를 이끄는 기회도 만날 수 있습니다.</p><span class="tag">${state.activityClub==='none'?'상설동아리 미가입':state.captain?'동아리 기장으로 활동 중':'함께 성장하는 동아리원'}</span></section><section class="card club-card"><div class="big-icon">⚑</div><div class="eyebrow">STUDENT COUNCIL</div><h3 style="margin-top:12px">${esc(state.councilRole||'아직은 일반 학생')}</h3><p>학생회 활동으로 리더십과 신뢰를 쌓으세요. 선거가 열리면 출마할 수 있고, 사회성과 리더십에 따라 결과가 달라집니다.</p><span class="tag">리더십 ${Math.round(state.stats.leadership)} / 100</span></section><section class="card club-card"><div class="big-icon">✦</div><div class="eyebrow">MY DIRECTION</div><h3 style="margin-top:12px">나의 선택과목</h3><p>${state.electives.length?state.electives.map(id=>esc(clubName(E.electives,id))).join(' · '):'2학년 2학기가 되면 관심 분야의 과목 2개를 선택해요. 지금은 다양한 경험을 해봐도 좋아요.'}</p><span class="tag">${state.electives.length?'수강 선택 완료':'2학년 2학기 개방'}</span></section></div>`)}
function journal(){shell(`${heading('LITTLE MOMENTS','그때, 우리는.','작은 선택들이 모여 하나의 학교생활이 됩니다.','MY JOURNAL')}<div class="card journal log-full">${recentLog(999)}</div>`)}
function future(){const p=E.getProfile(state);if(state.turn<48){shell(`${heading('THE NEXT CHAPTER','너의 다음 페이지.','결말은 아직 정해지지 않았어요. 지금의 선택을 쌓아보세요.','AFTER GSA')}<section class="hero"><div class="hero-copy"><div class="hero-kicker">졸업까지 ${48-state.turn}주</div><h2>성적표 하나로는<br>설명할 수 없는 너.</h2><p>학업, 연구, 사회성, 리더십이 모여<br>다음 여정을 향한 준비가 됩니다.</p></div>${campus}</section><div class="notice">6학기를 모두 마치면 대학 3곳까지 지원할 수 있어요. 대학별 결과는 게임 속 성적·활동·무작위 요소로 정해지는 가상 결과입니다.</div><div class="columns"><div class="card empty">지금은 나만의 가능성을 탐색하는 시간.<br>학교생활 탭에서 다음 한 주를 보내보세요.</div>${profile()}</div>`);return;}shell(`${heading('CLASS OF YOUR OWN','우리의 3년, 그리고 시작.','고생했어. 이제 너의 다음 이야기를 만나볼 시간.','GRADUATION')}<section class="graduation"><div class="eyebrow" style="color:#b9d6a2">${esc(state.name)}의 졸업 앨범</div><h2>${esc(p.strength||'나만의 길을 찾아낸 3년')}</h2><p>${esc(p.ending)}<br>누적 평점 ${p.gpa.toFixed(2)} / 4.3 · 연구 역량 ${Math.round(state.stats.research)} · 사회성 ${Math.round(state.stats.social)}<br>${esc(state.councilRole||'평범한 교실의 한 자리')}에서, ${esc(clubName(E.activityClubs,state.activityClub))}에서. 모든 순간이 너의 일부가 되었어.</p></section>${state.admissions?admissionResults():`<div class="section-title"><h2>대학에 지원하기</h2><small>최대 3곳 · 한 번만 지원할 수 있어요</small></div><p class="notice">실제 대학명을 사용한 가상 진학 시뮬레이션입니다. 아래 성향과 합격 여부는 실제 선발 기준·합격 가능성과 무관합니다.</p><div class="university-grid">${E.universities.map(u=>`<label class="university"><input name="university" type="checkbox" value="${u.id}">${esc(u.name)}<p>${esc(u.description||u.focus||'학업과 활동을 함께 보는 가상의 진학 경로')}</p></label>`).join('')}</div><button class="primary" data-do="apply" style="margin-top:22px">지원하고 결과 확인하기 ${icon('arrow')}</button>`}<button class="secondary" data-do="new" style="margin-top:25px">새로운 3년을 살아보기</button>`);}
function admissionResults(){const list=Array.isArray(state.admissions)?state.admissions:state.admissions.results||[];return `<div class="section-title"><h2>너의 새로운 출발</h2><small>가상 진학 결과</small></div>${list.map(r=>`<div class="card result"><div><h3>${esc(r.name||clubName(E.universities,r.id))}</h3><p>${esc(r.reason||r.message||'3년의 학업과 활동을 바탕으로 한 게임 속 결과입니다.')}</p></div><span class="${r.accepted?'accepted':'rejected'}">${r.accepted?'합격':'불합격'}</span></div>`).join('')}<p class="notice" style="margin-top:20px">어떤 결과여도, 지난 3년의 경험이 사라지는 건 아니에요. 대학명만으로 너의 학교생활을 평가하지 않습니다.</p>`}
function render(){if(!state)setup();else({home,grades,clubs,journal,future}[view]||home)();renderModal();}
function renderModal(){const root=$('#modal-root');root.innerHTML='';if(!state)return;const p=E.getPhase(state);let html='';if(state.pendingEvent){const e=state.pendingEvent;html=`<div class="eyebrow">A MOMENT TO CHOOSE</div><h2 id="modal-title">${esc(e.title)}</h2><p>${esc(e.description)}</p><div class="choices">${e.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><strong>${esc(c.label)}</strong><small>${esc(c.description||'')}</small></button>`).join('')}</div>`;}else if(p.needsElectives){html=`<div class="eyebrow">CHOOSE YOUR DIRECTION</div><h2 id="modal-title">2학년 2학기,<br>나의 분야를 선택할 시간.</h2><p>앞으로 배울 선택과목 2개를 골라주세요. 관심 분야와 동아리 경험을 함께 생각해봐도 좋아요. 과목명은 게임용 예시입니다.</p><div class="elective-grid">${E.electives.map(e=>`<label class="check-card"><input type="checkbox" name="elective" value="${e.id}">${esc(e.name)}</label>`).join('')}</div><button class="primary" data-do="electives">선택과목 2개 확정하기</button>`;}else if(semesterNotice){const g=semesterNotice;html=`<div class="eyebrow">ONE CHAPTER COMPLETE</div><h2 id="modal-title">${g.year}학년 ${g.semester}학기를 마쳤어.</h2><p>바쁘게 지나간 한 학기, 너의 노력이 기록되었어.</p><div class="summary-cards" style="grid-template-columns:1fr 1fr"><div class="card summary-card"><small>이번 학기 평점</small><strong>${g.gpa.toFixed(2)}</strong></div><div class="card summary-card"><small>이수 학점</small><strong>${g.earnedCredits ?? g.credits}</strong></div></div><p>과목별 성적은 성적표 탭에서 볼 수 있어요.</p><button class="primary" data-do="dismiss">${state.turn>=48?'졸업 앨범 펼치기':'다음 이야기로'} ${icon('arrow')}</button>`;}if(html){root.innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${html}</section></div>`;root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>attempt(()=>{const r=E.chooseEvent(state,Number(b.dataset.choice));persist();render();if(r?.messages?.length)toast(r.messages.join(' '));}));root.querySelectorAll('[data-do]').forEach(b=>b.onclick=()=>dispatch(b.dataset.do));root.querySelectorAll('input[name="elective"]').forEach(i=>i.onchange=()=>{if(root.querySelectorAll('input:checked').length>2){i.checked=false;toast('선택과목은 2개까지 고를 수 있어요.');}});setTimeout(()=>root.querySelector('button,input')?.focus(),0);}}
function attempt(fn){try{fn();}catch(e){toast(e.message||'선택을 다시 확인해주세요.');}}
function bind(){$('[data-do="start"]')?.addEventListener('click',()=>dispatch('start'));document.querySelectorAll('.layout [data-do]:not([data-do="start"]),.sidebar [data-do]').forEach(b=>b.onclick=()=>dispatch(b.dataset.do));document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render();window.scrollTo({top:0,behavior:'instant'});});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{action=b.dataset.action;render();});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render();});document.querySelectorAll('input[name="university"]').forEach(i=>i.onchange=()=>{if(document.querySelectorAll('input[name="university"]:checked').length>3){i.checked=false;toast('대학은 최대 3곳까지 지원할 수 있어요.');}});}
function dispatch(what){attempt(()=>{if(what==='reroll'){const name=$('#student-name').value,ac=$('#academic-club').value,act=$('#activity-club').value;draft=E.create(name||'새로운 학생');render();$('#academic-club').value=ac;$('#activity-club').value=act;return;}if(what==='start'){draft.name=$('#student-name').value.trim()||'새로운 학생';E.setClubs(draft,$('#academic-club').value,$('#activity-club').value);state=draft;view='home';persist();render();window.scrollTo({top:0,behavior:'instant'});return;}if(what==='new'){if(state&&!confirm('현재 진행을 지우고 새로운 학교생활을 시작할까요?'))return;state=null;draft=E.create('새로운 학생');view='home';action='study';mode='normal';semesterNotice=null;try{localStorage.removeItem(KEY);}catch(e){}render();window.scrollTo({top:0,behavior:'instant'});return;}if(what==='advance'){const result=E.advance(state,action,mode);mode='normal';if(result.semesterResult)semesterNotice=result.semesterResult;persist();render();if(result.messages?.length)toast(result.messages.slice(0,2).join(' '));return;}if(what==='electives'){const ids=[...document.querySelectorAll('input[name="elective"]:checked')].map(i=>i.value);if(ids.length!==2){toast('선택과목을 정확히 2개 골라주세요.');return;}E.chooseElectives(state,ids);persist();render();return;}if(what==='dismiss'){semesterNotice=null;if(state.turn>=48)view='future';render();return;}if(what==='apply'){const ids=[...document.querySelectorAll('input[name="university"]:checked')].map(i=>i.value);if(!ids.length){toast('지원할 대학을 1~3곳 선택해주세요.');return;}E.applyUniversities(state,ids);persist();render();return;}});}
document.addEventListener('keydown',e=>{const modal=$('.modal');if(!modal||e.key!=='Tab')return;const targets=[...modal.querySelectorAll('button,input,select,[tabindex="0"]')].filter(x=>!x.disabled);const first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
render();
})();
